/**
 * ============================================================================
 * 視覺藝術作品署名與靈感宣告 (ATTRIBUTION & INSPIRATION DECLARATION)
 * ============================================================================
 * 作者 (Author / Code Adaptor): Uncler M
 * 靈感啟發來源 (Inspired By): Lawa - "P5js | 星云回声 音乐可视化"
 * 原始作品討論 (Original Note): http://xhslink.com/o/8bH10rS4zQC
 * 授權協議 (License): Creative Commons Attribution-NonCommercial-ShareAlike 4.0 (CC BY-NC-SA 4.0)
 * 
 * [說明 / Notice]
 * 本作品由 Uncler M 編寫與視聽化對應。演算法靈感取材自 Lawa 創作之「迷幻星雲迴聲
 * 與無限宇宙深淵下墜」視覺概念。
 * 專為 4K MV Visual Integration Editor 專案打造。
 * ============================================================================
 */

let NUM_NEBULA_PARTICLES = 360;
let nebulaParticles = [];
let echoRings = [];
let fallZ = 0;
let spiralAngle = 0;

let smoothedSubBass = 0.0;
let smoothedPercussive = 0.0;
let smoothedMid = 0.0;

setup = () => {
  p5.disableFriendlyErrors = true;
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 1.0);
  ellipseMode(CENTER);

  // 初始化星雲粒子佇列
  for (let i = 0; i < NUM_NEBULA_PARTICLES; i++) {
    let theta = random(TWO_PI);
    let radius = random(40, 500);
    nebulaParticles.push({
      theta: theta,
      r: radius,
      z: random(0, 1200),
      speed: random(0.005, 0.02),
      size: random(3.0, 9.0),
      hueOffset: random(-40, 40)
    });
  }

  // 初始化多重星雲迴聲環
  for (let k = 0; k < 6; k++) {
    echoRings.push({
      z: k * 200,
      baseRadius: 120 + k * 70,
      echoPhase: k * 0.4
    });
  }
};

draw = () => {
  // 1. 動態音訊信號平滑處理
  let rawSubBass = (typeof sub_bass !== 'undefined') ? sub_bass : (typeof sub_bass_ratio !== 'undefined' ? sub_bass_ratio : (mouseIsPressed ? 0.85 : 0.22));
  let rawPercussive = (typeof percussive !== 'undefined') ? percussive : (mouseIsPressed ? 0.9 : 0.1);
  let rawMid = (typeof mid !== 'undefined') ? mid : (typeof mid_ratio !== 'undefined' ? mid_ratio : 0.3);

  smoothedSubBass += (rawSubBass - smoothedSubBass) * 0.14;
  smoothedPercussive += (rawPercussive - smoothedPercussive) * 0.28;
  smoothedMid += (rawMid - smoothedMid) * 0.18;

  // 2. 宇宙深淵無限下墜速度
  fallZ += 4.0 + smoothedSubBass * 16.0;
  spiralAngle += 0.005 + smoothedMid * 0.015;

  // 3. 迷幻發光沖刷背景
  background(265, 45, 5, 0.22);

  let cx = width * 0.5;
  let cy = height * 0.5;
  let currentHue = (typeof chord_hue !== 'undefined' && chord_hue > 0) ? chord_hue : 270;

  // 4. 重拍觸發「星雲脈衝殘影爆發 (Nebula Echo Burst)」
  let echoBoost = smoothedPercussive * 1.5;

  // 5. 渲染 3D 多重星雲迴聲環 (Nebula Echo Rings)
  noFill();
  for (let k = 0; k < echoRings.length; k++) {
    let ring = echoRings[k];
    let worldZ = (ring.z - fallZ) % 1200;
    if (worldZ < 20) worldZ += 1200;

    let scale = 450 / (450 + worldZ);
    let dynRadius = (ring.baseRadius + sin(spiralAngle * 2 + ring.echoPhase) * 35.0 + smoothedSubBass * 120.0) * scale;
    let ringAlpha = map(worldZ, 20, 1200, 0.85, 0.05);
    let ringHue = (currentHue + k * 25) % 360;

    stroke(ringHue, 80, 95 + echoBoost * 30, ringAlpha * (0.6 + echoBoost));
    strokeWeight((2.0 + smoothedSubBass * 4.0) * scale);
    ellipse(cx, cy, dynRadius * 2.0, dynRadius * 2.0);
  }

  // 6. 渲染 3D 迷幻星雲粒子群 (Nebula Particles Update & Render)
  let projParticles = [];

  for (let i = 0; i < NUM_NEBULA_PARTICLES; i++) {
    let p = nebulaParticles[i];
    p.theta += p.speed * (1.0 + smoothedMid * 1.5);

    let worldZ = (p.z - fallZ) % 1200;
    if (worldZ < 10) worldZ += 1200;

    // 加入 3D Perlin 噪聲動態流體震波
    let noiseVal = (noise(p.r * 0.003, worldZ * 0.002, spiralAngle) - 0.5) * 80.0 * smoothedMid;
    let dynR = (p.r + noiseVal + smoothedSubBass * 140.0);

    let rx = dynR * cos(p.theta + spiralAngle);
    let ry = dynR * sin(p.theta + spiralAngle);

    let scale = 450 / (450 + worldZ);
    projParticles.push({
      px: cx + rx * scale,
      py: cy + ry * scale,
      pz: worldZ,
      size: p.size * scale * (1.0 + smoothedSubBass * 0.8),
      hue: (currentHue + p.hueOffset) % 360
    });
  }

  // 按 Z 深度排序
  projParticles.sort((a, b) => b.pz - a.pz);

  // 繪製發光星雲粒子光斑
  for (let i = 0; i < projParticles.length; i++) {
    let pp = projParticles[i];
    let alpha = map(pp.pz, 10, 1200, 0.95, 0.1);

    // 外層光暈 (Outer Glow)
    noStroke();
    fill(pp.hue, 85, 100, alpha * 0.35);
    ellipse(pp.px, pp.py, pp.size * 2.8, pp.size * 2.8);

    // 核心光斑
    fill((pp.hue + 30) % 360, 40, 100, alpha * 0.9);
    ellipse(pp.px, pp.py, pp.size, pp.size);
  }

  // 7. 重拍繁星光芒脈衝
  if (smoothedPercussive > 0.6) {
    fill(0, 0, 100, smoothedPercussive * 0.4);
    rect(0, 0, width, height);
  }
};

// === 運行時防崩潰護欄與 DOM 代理 Stubs ===
